css:
.prin{--ink:#0f172a; --ink2:#334155; --ink3:#64748b;
  --paper:#F4F7FB; --paper2:#F8FAFC; --card:#FFFFFF;
  --line:#E2E8F0; --line2:#F1F5F9;
  --k:#16181C; --c:#2563EB; --m:#C8005F; --y:#F59E0B;
  --hv:#DC2626; --heat:#F97316; --ok:#059669;
  --dark:#1E252F; --dark2:#151A23;
  --mono:'Pretendard Variable',Pretendard,-apple-system,'Apple SD Gothic Neo','Noto Sans KR','Segoe UI',sans-serif;
  --sans:'Pretendard Variable',Pretendard,-apple-system,'Apple SD Gothic Neo','Noto Sans KR','Segoe UI',sans-serif;
  --r:14px; --r-sm:10px;
  --sh:0 1px 2px rgba(15,23,42,.05),0 1px 3px rgba(15,23,42,.06);}
.prin *{box-sizing:border-box}
.prin{scroll-behavior:smooth}
.prin{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);
  font-weight:500;line-height:1.7;-webkit-font-smoothing:antialiased;letter-spacing:-.01em}
.prin .wrap{max-width:1180px;margin:0 auto;padding:0 20px}
.prin .layout{display:grid;grid-template-columns:220px 1fr;gap:28px;align-items:start}
.prin header.top{background:var(--dark);color:#fff;border-bottom:1px solid rgba(255,255,255,.06)}
.prin .top-in{max-width:1180px;margin:0 auto;padding:30px 20px 26px}
.prin .eyebrow{font-size:11px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;color:#94a3b8;margin:0 0 12px}
.prin h1{font-size:clamp(24px,4vw,38px);line-height:1.18;margin:0;font-weight:900;letter-spacing:-.03em;color:#fff}
.prin h1 em{font-style:normal;color:#93c5fd}
.prin .sub{margin:12px 0 0;color:#cbd5e1;font-size:14.5px;max-width:64ch;font-weight:600;line-height:1.65}
.prin .sub b{color:#fff;font-weight:800}
.prin .meta{display:flex;flex-wrap:wrap;gap:6px;margin-top:18px}
.prin .chip{font-size:11px;font-weight:700;letter-spacing:0;padding:5px 11px;border:1px solid rgba(255,255,255,.14);
  border-radius:999px;color:#cbd5e1;background:rgba(255,255,255,.06)}
.prin .chip b{color:#fff;font-weight:800}
.prin nav.side{position:sticky;top:12px;padding:20px 0;font-size:13px}
.prin nav.side .nav-t{font-size:10.5px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;color:var(--ink3);
  padding:0 4px 10px;margin-bottom:6px}
.prin nav.side .navlist{display:flex;flex-direction:column;gap:3px;background:var(--card);border:1px solid var(--line);
  border-radius:var(--r);padding:8px;box-shadow:var(--sh)}
.prin nav.side a{display:flex;align-items:center;gap:9px;padding:8px 10px;color:var(--ink2);text-decoration:none;
  border-radius:var(--r-sm);font-weight:700;transition:.15s;border-left:none;margin-left:0}
.prin nav.side a:hover{background:var(--paper2);color:var(--ink)}
.prin nav.side a.on{background:var(--ink);color:#fff;font-weight:800}
.prin nav.side a .n{font-size:11px;font-weight:900;color:var(--ink3);min-width:20px;font-variant-numeric:tabular-nums}
.prin nav.side a.on .n{color:#93c5fd}
.prin main{padding:20px 0 90px;min-width:0}
.prin section{margin-bottom:28px;scroll-margin-top:16px;background:var(--card);border:1px solid var(--line);
  border-radius:18px;padding:22px 22px 10px;box-shadow:var(--sh)}
.prin .sec-h{display:flex;align-items:baseline;gap:12px;padding-bottom:14px;border-bottom:1px solid var(--line2);margin-bottom:18px}
.prin .sec-n{font-size:11px;font-weight:900;letter-spacing:.14em;color:var(--c);padding-top:6px;font-variant-numeric:tabular-nums}
.prin h2{font-size:clamp(19px,2.4vw,24px);margin:0;font-weight:900;letter-spacing:-.03em;color:var(--ink)}
.prin h2 span{color:var(--ink3);font-weight:700;font-size:.62em;letter-spacing:0;margin-left:8px}
.prin h3{font-size:15.5px;margin:28px 0 10px;font-weight:900;letter-spacing:-.02em;display:flex;align-items:center;gap:9px}
.prin h3::before{content:"";width:4px;height:16px;border-radius:2px;background:var(--c);flex:none}
.prin h4{font-size:14px;margin:20px 0 8px;font-weight:800;color:var(--ink2)}
.prin p{margin:0 0 12px}
.prin .lead{font-size:15px;color:var(--ink2);margin-bottom:18px;font-weight:600;line-height:1.7}
.prin .lead b,.prin p b{font-weight:800;color:var(--ink)}
.prin .card{background:var(--paper2);border:1px solid var(--line);border-radius:var(--r);padding:18px 20px;margin:16px 0}
.prin .fig{background:var(--card);border:1px solid var(--line);border-radius:var(--r);margin:18px 0;overflow:hidden;box-shadow:var(--sh)}
.prin .fig-h{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;
  padding:10px 14px;border-bottom:1px solid var(--line2);background:var(--paper2)}
.prin .fig-t{font-size:11.5px;font-weight:900;letter-spacing:0;text-transform:none;color:var(--ink2)}
.prin .fig-b{padding:12px 14px 16px}
.prin .cap{font-size:12.5px;color:var(--ink3);padding:0 14px 14px;margin:0;font-weight:600}
.prin .note{border-left:4px solid var(--c);background:#EFF6FF;padding:12px 15px;margin:16px 0;
  border-radius:0 var(--r-sm) var(--r-sm) 0;font-size:14px;color:#1e3a8a}
.prin .warn{border-left:4px solid var(--hv);background:#FEF2F2;padding:12px 15px;margin:16px 0;
  border-radius:0 var(--r-sm) var(--r-sm) 0;font-size:14px;color:#7f1d1d}
.prin .warn b,.prin .note b{font-weight:800}
.prin .warn .tag,.prin .note .tag{font-size:10.5px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;display:block;margin-bottom:4px}
.prin .warn .tag{color:var(--hv)}
.prin .note .tag{color:var(--c)}
.prin .tw{overflow-x:auto;margin:14px 0;border:1px solid var(--line);border-radius:var(--r-sm)}
.prin table{width:100%;border-collapse:collapse;font-size:13.5px;background:var(--card);min-width:480px}
.prin th{background:#F1F5F9;color:var(--ink2);text-align:left;padding:9px 12px;font-weight:900;font-size:11.5px;letter-spacing:0;white-space:nowrap}
.prin td{padding:9px 12px;border-bottom:1px solid var(--line2);vertical-align:top;font-weight:600;color:var(--ink2)}
.prin tbody tr:last-child td{border-bottom:none}
.prin tbody tr:nth-child(even){background:#FAFBFD}
.prin td.pn{font-size:12.5px;font-weight:800;color:var(--ink);white-space:nowrap}
.prin td.num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
.prin .ctrl{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.prin button.b{font-family:var(--sans);font-size:12px;font-weight:800;letter-spacing:0;padding:7px 13px;
  border:1px solid var(--line);background:var(--card);color:var(--ink2);border-radius:999px;cursor:pointer;transition:.14s}
.prin button.b:hover{border-color:var(--c);color:var(--c)}
.prin button.b.on{background:var(--c);border-color:var(--c);color:#fff;box-shadow:0 3px 10px rgba(37,99,235,.3)}
.prin button.b:focus-visible{outline:2px solid var(--c);outline-offset:2px}
.prin .steps{display:flex;gap:4px;flex-wrap:wrap;border:none;border-radius:999px;overflow:hidden;background:var(--paper2);padding:4px}
.prin .steps button{font-family:var(--sans);font-size:12px;font-weight:800;padding:7px 12px;border:none;border-right:none;
  background:transparent;color:var(--ink3);cursor:pointer;transition:.14s;border-radius:999px}
.prin .steps button:hover{background:#fff;color:var(--ink)}
.prin .steps button.on{background:var(--ink);color:#fff}
.prin .steps button:focus-visible{outline:2px solid var(--c);outline-offset:-2px}
.prin svg{display:block;width:100%;height:auto;max-width:100%}
.prin .svg-cap{font-family:var(--sans);font-size:9.5px;fill:var(--ink3);letter-spacing:0;font-weight:700}
.prin .lbl{font-family:var(--sans);font-size:10.5px;fill:var(--ink2);font-weight:800}
.prin .lbl-s{font-family:var(--sans);font-size:9px;fill:var(--ink3);font-weight:700}
.prin .leader{stroke:var(--line);stroke-width:1}
.prin .hl{transition:opacity .3s,stroke-width .3s}
.prin .panel{display:grid;grid-template-columns:1fr;gap:0;border-top:1px solid var(--line2);background:var(--paper2)}
.prin .panel-in{padding:14px 16px}
.prin .panel-k{font-size:10.5px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;color:var(--c);margin-bottom:5px}
.prin .panel-t{font-size:16.5px;font-weight:900;margin:0 0 6px;letter-spacing:-.02em}
.prin .panel-d{font-size:14px;color:var(--ink2);margin:0;font-weight:600}
.prin .readout{display:flex;gap:0;border-top:1px solid var(--line2);flex-wrap:wrap;background:#fff}
.prin .ro{flex:1;min-width:112px;padding:10px 14px;border-right:1px solid var(--line2)}
.prin .ro:last-child{border-right:none}
.prin .ro-k{font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3)}
.prin .ro-v{font-size:14.5px;font-weight:900;margin-top:2px;color:var(--ink)}
.prin .g2{display:grid;grid-template-columns:repeat(auto-fit,minmax(258px,1fr));gap:12px;margin:16px 0}
.prin .mini{background:var(--paper2);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}
.prin .mini-k{font-size:10.5px;font-weight:900;letter-spacing:.1em;text-transform:uppercase;color:var(--ink3);margin-bottom:6px}
.prin .mini-t{font-weight:900;font-size:15px;margin:0 0 6px;letter-spacing:-.02em}
.prin .mini p{font-size:13.5px;color:var(--ink2);margin:0;font-weight:600}
.prin ul,.prin ol{margin:0 0 12px;padding-left:22px}
.prin li{margin-bottom:6px;font-size:14.5px;font-weight:600;color:var(--ink2)}
.prin li b{color:var(--ink);font-weight:800}
.prin ul.tight li{margin-bottom:3px}
.prin code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:.88em;background:var(--paper2);padding:1px 6px;
  border-radius:6px;border:1px solid var(--line2);color:var(--ink)}
.prin .en{font-size:.94em;font-weight:800;color:var(--ink)}
.prin .v{font-weight:900;color:var(--ink);font-variant-numeric:tabular-nums}
.prin .v.neg{color:var(--hv)}
.prin .chk{list-style:none;padding:0;margin:12px 0}
.prin .chk li{display:flex;gap:11px;padding:12px 14px;border:1px solid var(--line);border-radius:var(--r-sm);
  font-size:14.5px;margin:0 0 8px;background:var(--paper2);font-weight:700;color:var(--ink)}
.prin .chk li:last-child{border-bottom:1px solid var(--line)}
.prin .chk .q{font-size:11px;color:#fff;background:var(--c);font-weight:900;min-width:24px;height:24px;border-radius:999px;
  display:inline-flex;align-items:center;justify-content:center;padding:0;flex:none;margin-top:1px}
.prin footer{border-top:1px solid var(--line);padding:22px 0 40px;font-size:12.5px;color:var(--ink3);font-weight:600}
.prin footer .mono{font-family:var(--sans)}
@media (max-width:900px){.prin .layout{grid-template-columns:minmax(0,1fr);gap:0}
.prin .layout>*{min-width:0}
.prin nav.side .navlist{max-width:100%}
.prin nav.side{position:static;padding:14px 0 0;margin-bottom:6px}
.prin nav.side .navlist{flex-direction:row;flex-wrap:nowrap;overflow-x:auto;gap:4px;scrollbar-width:none;padding:6px}
.prin nav.side .navlist::-webkit-scrollbar{display:none}
.prin nav.side a{border-left:none;padding:7px 11px;margin-left:0;white-space:nowrap;flex:none}
.prin nav.side a.on{border-bottom:none}
}@media (prefers-reduced-motion:reduce){.prin{scroll-behavior:auto}
}.prin .xray{background:#0B1220;border:1px solid rgba(255,255,255,.1);border-radius:var(--r);margin:20px 0;overflow:hidden}
.prin .xray .xr-h{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;
  padding:10px 14px;border-bottom:1px solid rgba(255,255,255,.08);background:#111a2b}
.prin .xray .xr-t{font-size:11.5px;font-weight:900;letter-spacing:0;text-transform:none;color:#93c5fd}
.prin .xray .xr-b{padding:12px 14px 16px}
.prin .xray button.b{background:rgba(255,255,255,.06);border-color:rgba(255,255,255,.14);color:#cbd5e1}
.prin .xray button.b:hover{border-color:#93c5fd;color:#93c5fd}
.prin .xray button.b.on{background:#3b82f6;border-color:#3b82f6;color:#fff}
.prin .xray .steps{border-color:transparent;background:rgba(255,255,255,.06)}
.prin .xray .steps button{background:transparent;border-right-color:transparent;color:#94a3b8}
.prin .xray .steps button:hover{background:rgba(255,255,255,.1);color:#e2e8f0}
.prin .xray .steps button.on{background:#3b82f6;color:#fff}
.prin .xray .xr-p{border-top:1px solid rgba(255,255,255,.08);padding:14px 16px}
.prin .xray .xr-k{font-size:10.5px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;color:#93c5fd;margin-bottom:5px}
.prin .xray .xr-tt{font-size:16.5px;font-weight:900;margin:0 0 6px;color:#f1f5f9;letter-spacing:-.02em}
.prin .xray .xr-d{font-size:14px;color:#cbd5e1;margin:0;font-weight:600}
.prin .xray .xr-cap{padding:0 16px 14px;margin:0;font-size:12.5px;color:#94a3b8;font-weight:600}
.prin .xray .xr-cap b{color:#e2e8f0}
.prin .xray svg{cursor:grab;touch-action:pan-y}
.prin .xray svg.drag{cursor:grabbing}
.prin .xray .xr-hint{font-size:10.5px;color:#64748b;padding:0 16px 12px;letter-spacing:0;font-weight:700}
.prin .xray .xr-legend{display:flex;flex-wrap:wrap;gap:6px 18px;padding:12px 16px 4px;border-top:1px solid rgba(255,255,255,.08)}
.prin .xray .xr-legend div{display:flex;align-items:center;gap:8px;font-size:12px;color:#cbd5e1;padding:3px 0;font-weight:700}
.prin .xray .xr-legend i{width:11px;height:11px;border-radius:3px;flex:none;display:block}
.prin .xray .xr-seq{list-style:none;margin:12px 0 0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(232px,1fr));gap:2px 20px}
.prin .xray .xr-seq li{font-size:13px;color:#cbd5e1;padding:4px 0;display:flex;gap:9px;align-items:baseline;font-weight:600}
.prin .xray .xr-seq .n{font-size:11px;font-weight:900;color:#93c5fd;flex:none;min-width:15px}
.prin .xray .xr-seq b{color:#f8fafc;font-weight:800}
.prin .xray .xr-zoom{font-size:11px;font-weight:800;color:#cbd5e1;border:1px solid rgba(255,255,255,.14);padding:4px 10px;border-radius:999px;white-space:nowrap}
.prin .xray .xr-b{position:relative}
.prin .xray .xr-tip{position:absolute;pointer-events:none;opacity:0;transform:translate(-50%,-130%);
  background:#111a2b;border:1px solid #3b82f6;border-radius:8px;padding:6px 10px;
  font-size:11.5px;font-weight:800;color:#f1f5f9;white-space:nowrap;box-shadow:0 8px 24px rgba(0,0,0,.5);z-index:5;max-width:280px;transition:opacity .1s}
.prin .xray .xr-tip .d{display:block;font-size:11px;color:#cbd5e1;white-space:normal;margin-top:3px;font-weight:600}
.prin .xray .xr-colsel{display:inline-flex;gap:3px;margin-left:4px}
.prin .xray .xr-colsel .cb{font-size:11px;font-weight:900;width:28px;padding:6px 0;border:1px solid rgba(255,255,255,.14);
  background:rgba(255,255,255,.06);color:var(--cc);border-radius:999px;cursor:pointer}
.prin .xray .xr-colsel .cb:hover{border-color:var(--cc)}
.prin .xray .xr-colsel .cb.on{background:var(--cc);color:#08131A;border-color:var(--cc)}
.prin .q7 .fig-b{padding:10px 12px 4px}
.prin .q7 svg{cursor:pointer}
.prin .q7cell{transition:opacity .25s}
.prin .q7 .ro-v a{color:var(--c);text-decoration:none;border-bottom:1px solid #bfdbfe}
.prin .q7 .ro-v a:hover{border-bottom-color:var(--c)}
.prin .swipe{display:none;font-size:11px;font-weight:700;color:var(--ink3);padding:0 14px 10px;margin:0}
@media (max-width:760px){.prin .wrap{padding:0 12px}
.prin main{padding:12px 0 60px}
.prin section{padding:16px 14px 6px;border-radius:16px;margin-bottom:16px}
.prin .top-in{padding:22px 14px 20px}
.prin h1{font-size:clamp(21px,6vw,27px)}
.prin .sub{font-size:13.5px}
.prin h2{font-size:19px}
.prin h2 span{display:block;margin:2px 0 0;font-size:12px}
.prin .lead{font-size:14.5px}
.prin .fig-b,.prin .xr-b{overflow-x:auto;-webkit-overflow-scrolling:touch;padding:12px 12px 14px}
.prin .fig-b>svg{min-width:760px}
.prin .q7 .fig-b>svg{min-width:760px}
.prin .xr-b>svg{min-width:900px}
.prin .swipe{display:block}
.prin button.b{font-size:12px;padding:9px 13px;min-height:38px}
.prin .steps{flex-wrap:nowrap;overflow-x:auto;-webkit-overflow-scrolling:touch}
.prin .steps button{white-space:nowrap;font-size:12px;padding:10px 13px;min-height:38px}
.prin .xray .xr-colsel .cb{width:32px;min-height:38px}
.prin .ctrl{gap:6px}
.prin .ro{min-width:100%;border-right:none;border-bottom:1px solid var(--line2)}
.prin .ro:last-child{border-bottom:none}
.prin .panel-in{padding:13px 14px}
.prin .panel-t{font-size:16px}
.prin .panel-d{font-size:13.5px}
.prin table{font-size:12.5px;min-width:420px}
.prin th,.prin td{padding:8px 10px}
.prin .g2{grid-template-columns:1fr}
.prin .seq,.prin .xr-seq{grid-template-columns:1fr}
.prin .chk li{font-size:14px}
}@media (max-width:420px){.prin h1{font-size:20px}
.prin .top-in{padding:18px 12px 16px}
}.prin .easy{border-left:4px solid var(--y);background:#FFFBEB;padding:12px 15px;margin:16px 0;
  border-radius:0 var(--r-sm) var(--r-sm) 0;font-size:14.5px;color:#78350f;font-weight:600}
.prin .easy .tag{font-size:10.5px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;display:block;margin-bottom:4px;color:#b45309}
.prin .easy b{font-weight:900;color:#451a03}
.prin .cmp{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:12px;margin:16px 0}
.prin .cmp .card2{background:var(--paper2);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px}
.prin .cmp .n2{font-size:22px;font-weight:900;color:var(--y);line-height:1}
.prin .cmp .t2{font-weight:900;font-size:15.5px;margin:8px 0 6px;letter-spacing:-.02em}
.prin .cmp .a2{font-size:14px;color:var(--ink2);margin:0 0 8px;font-weight:600}
.prin .cmp .r2{font-size:13px;color:var(--ink3);margin:0;padding-top:8px;border-top:1px dashed var(--line);font-weight:600}
.prin .cmp .r2 b{color:var(--ink2);font-weight:800}

.prin{background:transparent}
.prin header.top{border-radius:14px}
.prin .top-in{padding:26px 22px 22px}
.prin footer{border-top:none;padding:14px 4px 4px}
@media (max-width:760px){ .prin header.top{border-radius:12px} .prin .top-in{padding:20px 14px 18px} }

script:
(function(){
"use strict";
var reduce = false;   /* 애니메이션은 학습 내용이므로 자동 정지하지 않음 (각 그림에 일시정지 버튼 제공) */

/* ---------- 목차 하이라이트 ---------- */
/* 화면에 보이는 그림만 계산한다 — 모바일에서 8개 애니메이션이 동시에 돌면 느려진다 */
var VIS={};
function watchVis(id){
  var el=document.getElementById(id); if(!el) return;
  if(!('IntersectionObserver' in window)){ VIS[id]=true; return; }
  VIS[id]=true;          /* 관찰이 실패해도 멈추지 않도록 기본은 '보임' */
  new IntersectionObserver(function(es){
    es.forEach(function(en){ VIS[id]=en.isIntersecting; });
  },{rootMargin:'200px'}).observe(el);
}
function isVis(id){ return VIS[id]!==false; }

var links = Array.prototype.slice.call(document.querySelectorAll('nav.side a'));
var secs  = links.map(function(a){ return document.querySelector(a.getAttribute('href')); });
function onScroll(){
  var y = window.scrollY + 130, idx = 0;
  for (var i=0;i<secs.length;i++){ if (secs[i] && secs[i].offsetTop <= y) idx = i; }
