      m.textContent = '−'; m.setAttribute('fill', '#E8452A'); m.setAttribute('opacity', '0.95');
    } else if (ph < P_DEVE){
      if (isImage(i)){ m.textContent = '+'; m.setAttribute('fill', '#0E7A57'); m.setAttribute('opacity', '0.95'); }
      else { m.textContent = '−'; m.setAttribute('fill', '#E8452A'); m.setAttribute('opacity', '0.55'); }
    } else if (ph < P_BTR){
      m.textContent = isImage(i) ? '+' : '−';
      m.setAttribute('fill', isImage(i) ? '#0E7A57' : '#E8452A');
      m.setAttribute('opacity', '0.35');
    } else if (ph < P_CLN){
      m.textContent = '·'; m.setAttribute('fill', '#A9BAC9'); m.setAttribute('opacity', '0.5');
    } else { m.textContent = ''; }
    m.setAttribute('x', p[0]); m.setAttribute('y', p[1] + 4);
  }

  /* 드럼 위 토너 : 현상(우측) → 1차 전사(상단) 구간, 화상부만 */
  for (var j = 0; j < ND; j++){
    var a2 = norm(t + j * (360 / ND) + A_BCR);
    var ph2 = phaseOf(a2);
    var dd = dots[j];
    if (ph2 >= P_DEVE && ph2 < P_BTR && isImage(j)){
      var p2 = ptAt(a2, R - 5);
      dd.setAttribute('cx', p2[0]); dd.setAttribute('cy', p2[1]);
      dd.setAttribute('fill', '#008FB3'); dd.setAttribute('opacity', '0.92');
    } else { dd.setAttribute('opacity', '0'); }
  }

  /* 벨트 위 토너 : 1st BTR(x=446) → BUR(x=168) 좌향 이동 */
  for (var b = 0; b < NB; b++){
    var u = ((t / 240) + b / NB) % 1;
    var x = 446 - (446 - 168) * u;
    bDots[b].setAttribute('x', x - 6.5);
    bDots[b].setAttribute('opacity', String(0.9 * Math.min(1, (1 - u) * 5)));
  }

  /* LPH 빔 */
  lphBeam.setAttribute('opacity', (stage === 0 || stage === 2) ? '1' : '0.28');

  /* 용지 */
  var pp = pPath2.getPointAtLength(pU2 * pLen2);
  var pn = pPath2.getPointAtLength(Math.min(pLen2, pU2 * pLen2 + 6));
  var an = Math.atan2(pn.y - pp.y, pn.x - pp.x) * 180 / Math.PI;
  sheet2.setAttribute('transform', 'translate(' + pp.x + ',' + pp.y + ') rotate(' + an + ')');
  /* 닙(y≈149) 통과 후 토너 적재 */
  sToner2.setAttribute('width', (pp.x < 200 && pp.y < 152) ? 20 : 0);

  requestAnimationFrame(frame);
}
