function TC(n){ return n==='K'?C.tK:(n==='C'?C.tC:(n==='M'?C.tM:C.tY)); }

/* ===== 지오메트리 ===== */
var ST=[], LOD=0, NM='';
function nrm(p,ct){
  var ux=p[1][0]-p[0][0],uy=p[1][1]-p[0][1],uz=p[1][2]-p[0][2];
  var vx=p[2][0]-p[0][0],vy=p[2][1]-p[0][1],vz=p[2][2]-p[0][2];
  var nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx;
  var m=Math.sqrt(nx*nx+ny*ny+nz*nz)||1; nx/=m;ny/=m;nz/=m;
  if(ct){
    var fx=0,fy=0,fz=0,i;
    for(i=0;i<p.length;i++){fx+=p[i][0];fy+=p[i][1];fz+=p[i][2];}
    fx/=p.length;fy/=p.length;fz/=p.length;
    if((fx-ct[0])*nx+(fy-ct[1])*ny+(fz-ct[2])*nz<0){nx=-nx;ny=-ny;nz=-nz;}
  }
  return [nx,ny,nz];
}
function box(A,x0,y0,z0,x1,y1,z1,col,zn,o,only){
  var v=[[x0,y0,z0],[x1,y0,z0],[x1,y1,z0],[x0,y1,z0],
         [x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]];
  var q=[[0,1,2,3],[5,4,7,6],[4,0,3,7],[1,5,6,2],[3,2,6,7],[4,5,1,0]];
  var ct=[(x0+x1)/2,(y0+y1)/2,(z0+z1)/2];
  q.forEach(function(f,i){
    if(only && only.indexOf(i)<0) return;
    var p=[v[f[0]],v[f[1]],v[f[2]],v[f[3]]];
    A.push({p:p,c:col,z:zn,o:(o==null?1:o),n:nrm(p,ct),k:'s',l:LOD,nm:NM});
  });
}
function cyl(A,cx,cy,z0,z1,r,col,zn,o,N){
  N=N||12; var ct=[cx,cy,(z0+z1)/2],a=[],i;
  for(i=0;i<N;i++)a.push(2*Math.PI*i/N);
  for(i=0;i<N;i++){
    var a1=a[i],a2=a[(i+1)%N];
    var p=[[cx+r*Math.cos(a1),cy+r*Math.sin(a1),z0],[cx+r*Math.cos(a2),cy+r*Math.sin(a2),z0],
           [cx+r*Math.cos(a2),cy+r*Math.sin(a2),z1],[cx+r*Math.cos(a1),cy+r*Math.sin(a1),z1]];
    A.push({p:p,c:col,z:zn,o:(o==null?1:o),n:nrm(p,ct),k:'s',l:LOD,nm:NM});
  }
  var c0=[],c1=[];
  for(i=0;i<N;i++){
    c0.push([cx+r*Math.cos(a[N-1-i]),cy+r*Math.sin(a[N-1-i]),z0]);
    c1.push([cx+r*Math.cos(a[i]),cy+r*Math.sin(a[i]),z1]);
  }
  A.push({p:c0,c:col,z:zn,o:(o==null?1:o),n:nrm(c0,ct),k:'s',l:LOD,nm:NM});
  A.push({p:c1,c:col,z:zn,o:(o==null?1:o),n:nrm(c1,ct),k:'s',l:LOD,nm:NM});
}
