function desc(n){
  if(DESC[n]) return DESC[n];
  var b=n.replace(/\s*\([^)]*\)\s*$/,'').trim();
  if(DESC[b]) return DESC[b];
  b=b.replace(/\s+\d+$/,'').trim();
  if(DESC[b]) return DESC[b];
  b=b.replace(/\s+[KCMY]$/,'').trim();
  return DESC[b]||'';
}

