var PPD=[[300,272],[86,272],[42,306],[42,466],[42,556],[70,612],[240,618],
         [96,606],[26,566],[18,330],[30,296],[42,306],
         [42,466],[42,556],[70,612],[300,618]];
function mkSeg(P){
  var S=[],T=0,i;
  for(i=0;i<P.length-1;i++){
    var dx=P[i+1][0]-P[i][0],dy=P[i+1][1]-P[i][1],L=Math.sqrt(dx*dx+dy*dy);
    S.push({a:P[i],b:P[i+1],L:L,s:T}); T+=L;
  }
  return {S:S,T:T};
}
var S1=mkSeg(PP), S2=mkSeg(PPD), duplex=false;
var SEG=S1.S, TOT=S1.T;
var U_BTR2=(S1.S[2].s+S1.S[2].L)/S1.T, U_FUSE=(S1.S[3].s+S1.S[3].L)/S1.T;
/* 양면 : 1면 전사·정착 / 2면 전사·정착 경계 */
var D2_BTR1=(S2.S[2].s+S2.S[2].L)/S2.T, D2_FUSE1=(S2.S[3].s+S2.S[3].L)/S2.T,
    D2_REV=(S2.S[6].s+S2.S[6].L)/S2.T, D2_REJOIN=(S2.S[10].s+S2.S[10].L)/S2.T,
    D2_BTR2=(S2.S[11].s+S2.S[11].L)/S2.T, D2_FUSE2=(S2.S[12].s+S2.S[12].L)/S2.T;
function setDuplex(v){
  duplex=v;
  SEG=v?S2.S:S1.S; TOT=v?S2.T:S1.T;
  U_BTR2=v?D2_BTR2:(S1.S[2].s+S1.S[2].L)/S1.T;
  U_FUSE=v?D2_FUSE2:(S1.S[3].s+S1.S[3].L)/S1.T;
  pu=0;
}
function pathAt(u){
  var t=u*TOT,sg=SEG[SEG.length-1];
  for(var i=0;i<SEG.length;i++){ if(t<=SEG[i].s+SEG[i].L){ sg=SEG[i]; break; } }
  var k=(t-sg.s)/sg.L;
  return {x:sg.a[0]+(sg.b[0]-sg.a[0])*k,y:sg.a[1]+(sg.b[1]-sg.a[1])*k,
          dx:(sg.b[0]-sg.a[0])/sg.L,dy:(sg.b[1]-sg.a[1])/sg.L};
}

