  engine:['belt','drum','engine'], drum:['dcut'], feed:['feed'] };
var PAPERZ=['all','scan','fuse','engine','feed'];
function proj(p){
  var x=p[0]-cam.x,y=p[1]-cam.y,z=p[2]-cam.z;
  var cy=Math.cos(yaw),sy=Math.sin(yaw);
  var x1=x*cy+z*sy,z1=-x*sy+z*cy;
  var cp=Math.cos(pitch),sp=Math.sin(pitch);
  return [ORX+panX+x1*cam.s, ORY+panY-(y*cp-z1*sp)*cam.s, y*sp+z1*cp];
}
function rotN(n){
  var cy=Math.cos(yaw),sy=Math.sin(yaw),z1=-n[0]*sy+n[2]*cy;
  return n[1]*Math.sin(pitch)+z1*Math.cos(pitch);
}
var LT=(function(){ var v=[-0.40,0.82,0.41],m=Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);
  return [v[0]/m,v[1]/m,v[2]/m]; })();
var RGB={};
function rgb(hx){ if(RGB[hx])return RGB[hx];
  return (RGB[hx]=[parseInt(hx.substr(1,2),16),parseInt(hx.substr(3,2),16),parseInt(hx.substr(5,2),16)]); }
function col(hx,sh,near){
  var c=rgb(hx),f=(1-near)*0.40,r=c[0]*sh,g=c[1]*sh,b=c[2]*sh;
  r+=(BG[0]-r)*f; g+=(BG[1]-g)*f; b+=(BG[2]-b)*f;
  return 'rgb('+Math.round(r)+','+Math.round(g)+','+Math.round(b)+')';
}

/* ===== 동작 ===== */
var tt=0,pu=0,anim=!reduce,zone='all',showShell=true,drumSel='Y';
var lastList=[],pinned=[],hoverPr=null,hoverNm='';
function n360(a){ a%=360; if(a<0)a+=360; return a; }
function ph(a){ return n360(a-A_BCR)/360; }
var P_LPH=ph(A_LPH),P_DEVE=ph(A_DEVE),P_BTR=ph(A_BTR),P_CLN=ph(A_CLN);
function isImg(i){ return (i%5)!==0 && (i%7)!==3; }
function arc(cx,cy,z0,z1,r,a1,a2){
  var r1=a1*Math.PI/180,r2=a2*Math.PI/180;
  return [[cx+r*Math.cos(r1),cy+r*Math.sin(r1),z0],[cx+r*Math.cos(r2),cy+r*Math.sin(r2),z0],
          [cx+r*Math.cos(r2),cy+r*Math.sin(r2),z1],[cx+r*Math.cos(r1),cy+r*Math.sin(r1),z1]];
}
function ann(A,cx,cy,z,r0,r1,a1,a2,c2,zn,o){
  var t1=a1*Math.PI/180,t2=a2*Math.PI/180;
  quad(A,[[cx+r0*Math.cos(t1),cy+r0*Math.sin(t1),z],[cx+r1*Math.cos(t1),cy+r1*Math.sin(t1),z],
          [cx+r1*Math.cos(t2),cy+r1*Math.sin(t2),z],[cx+r0*Math.cos(t2),cy+r0*Math.sin(t2),z]],c2,zn,o);
}
function spoke(A,cx,cy,z1,r,a,zn){ ann(A,cx,cy,z1+2,r*0.22,r*0.92,a,a+16,C.mark,zn,0.9); }

function dyn(zn){
  var A=[],i,base=anim?tt*0.55:0;
  /* 드럼 · 현상기 절단 모형 */
  if(zn==='drum'){
    var d0=DRUM.filter(function(q){return q.n===drumSel;})[0]||DRUM[0];
    var Z0=300,Z1=502,dx=d0.x,T='dcut',DT=TC(d0.n),N=(lod()>=1?34:22);
    NM='Drum '+d0.n+' (광도체)';   cyl(A,dx,DCY,Z0,Z1,DRR,d0.c,T,0.55,N);
    NM='1st BTR';                  cyl(A,dx+6,479,Z0,Z1,9,C.btr,T,1,12);
    NM='BCR';                      cyl(A,dx-33,412,Z0,Z1,10,C.bcr,T,1,12);
    NM='Cleaning Blade';           cyl(A,dx-46,431,Z0,Z1,5,C.roll,T,1,10);
    NM='LPH';                      box(A,dx-8,386,Z0,dx+30,400,Z1, C.lph,T,1);
    NM='Development Roll';         cyl(A,dx+45,428,Z0,Z1,15,C.deve,T,1,14);
    NM='Developer Housing';        box(A,dx+26,378,Z0,dx+74,422,Z1, C.devh,T,0.30);
    NM='Developer (현상제 '+d0.n+')'; box(A,dx+29,381,Z0+6,dx+71,401,Z1-6, DT,T,1);
    NM='Toner Cartridge ('+d0.n+')';  box(A,dx-14,508,Z1-68,dx+34,552,Z1-20, DT,T,1);
    NM='IBT Belt';                 box(A,dx-52,472,Z0,dx+92,498,Z1, C.belt,T,0.34);
    /* ② 노광 빔 */
    NM='LPH 노광 빔';
    quad(A,[[dx+8,401,Z0+18],[dx+13,401,Z0+18],[dx+13,401,Z1-18],[dx+8,401,Z1-18]],'#FFE08A',T,0.5);
    quad(A,[[dx+9,401,Z1-10],[dx+13,401,Z1-10],[dx+12,DCY-DRR+2,Z1-10],[dx+10,DCY-DRR+2,Z1-10]],'#FFE08A',T,0.75);

    /* 전하 기호 : 대전부 − , 노광부 + */
    var NSY=13, kk2;
    for(kk2=0;kk2<NSY;kk2++){
      var sa=n360(base+kk2*(360/NSY)+A_BCR), sp2=ph(sa);
      var sr=sa*Math.PI/180, sx2=dx+(DRR+11)*Math.cos(sr), sy2=DCY+(DRR+11)*Math.sin(sr);
      if(sp2<P_LPH)       sym(A,sx2,sy2,Z1+8,'−',13,C.chg,T);
      else if(sp2<P_DEVE) sym(A,sx2,sy2,Z1+8, isImg(kk2)?'+':'−',13, isImg(kk2)?C.exp:C.chg, T);
    }
    /* ── 토너 경로 : Cartridge → Developer Housing → Development Roll → 닙 → Drum ──
       하우징에서 드럼으로 바로 튀지 않는다. 반드시 Development Roll 표면에 실려 닙까지 간다.
       닙(드럼·Deve 맞물림)은 용지 폭 전체에 걸쳐 접촉하므로 한 줄이 아니라 면으로 그린다. */
    var DVX=dx+45, DVY=428, DVR=15;
    var A_PICK=300, A_NIP=172.4, SPAN=A_PICK-A_NIP;   /* 하우징 픽업 → 닙 (128°) */
    function zc(k,cnt,pad){ return Z0+pad+(Z1-Z0-pad*2)*k/(cnt-1); }

    /* ① Developer Housing 안의 현상제 (폭 전체) */
    NM='토너 (현상제 · Developer Housing)';
    for(var hx=0;hx<6;hx++) for(var hr=0;hr<2;hr++) for(var hz=0;hz<3;hz++)
      dot(A, dx+34+hx*7, 386+hr*7, zc(hz,3,34), 4.2, DT, T, 1);

    /* ② Development Roll 표면에 실려 올라가는 현상제 산 (폭 전체).
       Deve 롤은 드럼과 반대 방향(시계)으로 돌아 닙에서 표면이 같은 방향으로 움직인다. */
    NM='토너 (Development Roll 표면)';
    var NA2=7;
    for(var ia=0;ia<NA2;ia++){
      var tv=((anim?tt/50:0.35)+ia/NA2)%1;
      var aa=(A_PICK-SPAN*tv)*Math.PI/180;
      var rx=DVX+(DVR+3.2)*Math.cos(aa), ry=DVY+(DVR+3.2)*Math.sin(aa);
      for(var kz=0;kz<4;kz++) dot(A, rx, ry, zc(kz,4,32), 4.0, DT, T, 1);
    }

    /* ③ 닙 — 드럼과 Development Roll 이 맞물리는 면 전체 */
    NM='토너 (닙 · 폭 전체 접촉)';
    for(var nz=0;nz<6;nz++){
      dot(A, dx+31.7, 429.8, zc(nz,6,28), 4.6, DT, T, 1);
      dot(A, dx+27.5, 430.6, zc(nz,6,28), 4.2, DT, T, 0.9);
    }

    /* ④ 드럼 표면으로 옮겨진 토너 화상
       입자를 얇고 촘촘하게 깔아 「얇은 토너층」으로 보이게 한다.
       각도 48분할 × 폭 9열 → 현상부터 1차 전사까지 면 전체에 고르게 분포. */
    NM='토너 (드럼 표면 화상)';
    var ND2=48, NZD=9;
    for(var td=0;td<ND2;td++){
      var da=n360(base+td*(360/ND2)+A_BCR), dp2=ph(da);
      var dr2=da*Math.PI/180;
      var sx2=dx+(DRR+2.0)*Math.cos(dr2), sy2=DCY+(DRR+2.0)*Math.sin(dr2);
      if(dp2>=P_DEVE && dp2<P_BTR){
        if(!isImg(td)) continue;                       /* 화상부에만 */
        for(var kz2=0;kz2<NZD;kz2++)
          dot(A, sx2, sy2, zc(kz2,NZD,24), 1.9, DT, T, 1);
      } else if(dp2>=P_BTR && dp2<P_CLN && td%3===0){
        /* 1차 전사 후 남은 잔류 토너 — Cleaning Blade 가 긁어낸다 */
        NM='토너 (1차 전사 후 잔류)';
        for(var kz3=0;kz3<5;kz3++)
          dot(A, sx2, sy2, zc(kz3,5,40), 1.5, C.resid, T, 0.75);
        NM='토너 (드럼 표면 화상)';
      }
    }
    /* Toner Cartridge → Developer Housing 보급 */
    NM='토너 보급 경로';
    for(var tc2=0;tc2<7;tc2++){
      var cv=((anim?tt/120:0.4)+tc2/7)%1;
      dot(A, dx+22, 504-(504-424)*cv, Z1-46, 3.8, DT, T, 1);
    }
    if(lod()>=1){
      NM='드럼 구동 기어';
      for(var gt=0;gt<12;gt++){
        var gA=gt*(360/12)*Math.PI/180, gx=dx+Math.cos(gA)*34, gy=DCY+Math.sin(gA)*34;
        box(A,gx-2.6,gy-2.6,Z0-16,gx+2.6,gy+2.6,Z0-6, C.motor,T,1);
      }
      cyl(A,dx,DCY,Z0-14,Z0-8,30,C.motor,T,1,16);
      NM='BCR Cleaner';    cyl(A,dx-41,392,Z0+6,Z1-6,7,C.roll,T,1,10);
      NM='Drum CLN Auger'; cyl(A,dx-54,452,Z0+6,Z1-6,6,C.roll,T,1,10);
      NM='Trickle outlet'; box(A,dx+70,376,Z0+8,dx+80,388,Z0+38, C.devh,T,1);
    }
    /* 표면 전위 : 원통 밴드 + 앞면 고리 */
    var NS=(lod()>=1?32:24);
    NM='드럼 표면 전위';
    for(i=0;i<NS;i++){
      var a1=n360(base+i*(360/NS)+A_BCR),a2=a1+(360/NS)-1.2;
      var p2=ph(a1),cc,oo=0.95;
      if(p2<P_LPH){ cc=C.chg; }
      else if(p2<P_DEVE){ cc=isImg(i)?C.exp:C.chg; oo=isImg(i)?0.95:0.45; }
      else if(p2<P_BTR){ if(!isImg(i)) continue; cc=DT; oo=1; }
      else if(p2<P_CLN){ cc=C.resid; oo=0.7; }
      else continue;
      quad(A,arc(dx,DCY,Z0+2,Z1-2,DRR+1.2,a1,a2),cc,T,oo);
      ann(A,dx,DCY,Z1+1.4,DRR*0.64,DRR+1.5,a1,a2,cc,T,oo);
    }
    for(i=0;i<8;i++) ann(A,dx,DCY,Z1+0.6,0,DRR*0.60,i*45,(i+1)*45+0.4,'#0F1A22',T,0.66);
    NM=''; spoke(A,dx,DCY,Z1,DRR,base,T);
    /* 드럼과 맞물리는 롤들은 반대 방향(시계)으로 돈다 — 닙에서 표면이 같은 방향으로 움직이게 */
    NM=''; spoke(A,dx+45,428,Z1,15,-base*2.1,T);
    NM=''; spoke(A,dx-33,412,Z1,10,-base*3.2,T);
    NM='IBT Belt 토너 ('+d0.n+')';
    for(i=0;i<5;i++){
      var u2=((anim?tt/170:0.4)+i/5)%1, tx=(dx+86)-((dx+86)-(dx-48))*u2;
      quad(A,[[tx-9,470.5,Z0+16],[tx+9,470.5,Z0+16],[tx+9,470.5,Z1-16],[tx-9,470.5,Z1-16]],DT,T,0.95);
    }
  }
  /* 벨트 위 4색 적층 */
  if(zn==='engine'||zn==='all'){
    var LY={Y:463.5,M:465.7,C:467.9,K:470.1};
    for(i=0;i<10;i++){
      var u3=((anim?tt/260:0.35)+i/10)%1, bx=452-(452-64)*u3;
      if(bx<70) continue;
      DRUM.forEach(function(d){
        if(bx>d.x) return;
        NM='IBT Belt 토너 ('+d.n+')';
        quad(A,[[bx-9,LY[d.n],ZF+30],[bx+9,LY[d.n],ZF+30],
                [bx+9,LY[d.n],ZB-30],[bx-9,LY[d.n],ZB-30]],TC(d.n),'belt',0.95);
      });
    }
  }
  /* 급지 : 리프트업 · 롤 회전 */
  var lift=(zn==='feed'&&anim)?5*(0.5+0.5*Math.sin(tt*0.045)):0;
  TY.forEach(function(ty,ti){
    var l=(ti===0)?lift:0;
    NM='Bottom Plate'; box(A,98,ty+5+l,72,546,ty+12+l,D-72, C.tray,'feed',1);
    /* 적재된 용지 다발 */
    NM='적재 용지';
    box(A,102,ty+12+l,76,542,ty+34+l,D-76, C.stack,'feed',1);
    for(var sk=0;sk<4;sk++)   /* 다발 결 표시 */
      quad(A,[[104,ty+16+l+sk*4.5,78],[540,ty+16+l+sk*4.5,78],
              [540,ty+16+l+sk*4.5,D-78],[104,ty+16+l+sk*4.5,D-78]],'#B9C7D0','feed',0.5);
    NM='Nudger Roll';  cyl(A,84,ty+30,252,348,9,C.roll,'feed',1,12);
    NM='Feed Roll';    cyl(A,56,ty+30,252,348,10,C.roll,'feed',1,12);
    NM='Retard Roll';  cyl(A,56,ty+10,252,348,10,C.roll,'feed',1,12);
    if(zn==='feed'){
      NM='';
      spoke(A,84,ty+30,348,9,-tt*(anim?2.4:0),'feed');
      spoke(A,56,ty+30,348,10,-tt*(anim?2.4:0),'feed');
      spoke(A,56,ty+10,348,10,tt*(anim?1.6:0),'feed');
    }
  });
  if(zn==='fuse'){ NM=''; spoke(A,64,556,ZB,20,-tt*(anim?1.4:0),'fuse'); }
  /* ── 용지 : 경로 곡선에 맞춰 휘어지는 띠로 그린다 ──
     예전에는 딱딱한 한 장의 판이어서 코너에서 방향만 바뀌었다.
     이제 진행 방향을 여러 조각으로 나눠 각 조각이 경로를 따라가므로 자연스럽게 휜다. */
  var ns=(zn==='feed')?3:1;
  var SLEN3=210, NSG=9, PZ0=152, PW=74;   /* A4 LEF : 길이 210 · 폭 296 */
  for(i=0;i<ns;i++){
    var uu=(zn==='feed')?((pu*0.34)+i*0.115)%0.34:(pu+i/ns)%1;
    /* 꼬리 ~ 머리 구간을 NSG 조각으로 샘플링 */
    var head=uu*TOT, tail=Math.max(0,head-SLEN3), PT=[], kk;
    for(kk=0;kk<=NSG;kk++){
      var dd=tail+(head-tail)*kk/NSG;
      PT.push(pathAt(Math.min(1,dd/TOT)));
    }
    var si,sg;
    /* 종이면 : 폭 4분할 × 길이 NSG 조각 */
    NM='용지';
    for(si=0;si<4;si++){
      var za=PZ0+si*PW, zb=PZ0+(si+1)*PW;
      for(sg=0;sg<NSG;sg++){
        var p1=PT[sg], p2=PT[sg+1];
        quad(A,[[p1.x,p1.y,za],[p2.x,p2.y,za],[p2.x,p2.y,zb],[p1.x,p1.y,zb]],C.paper,'paper',1);
      }
    }
    /* 2차 전사 후 토너가 묻고, 정착부를 지나면 융착된다 */
    function band3(off,za,zb,cc,nm2){
      NM=nm2;
      for(var s2=0;s2<NSG;s2++){
        var q1=PT[s2], q2=PT[s2+1];
        var tx=q2.x-q1.x, ty=q2.y-q1.y, m2=Math.sqrt(tx*tx+ty*ty)||1;
        var ox=-ty/m2*off, oy=tx/m2*off;
        quad(A,[[q1.x+ox,q1.y+oy,za],[q2.x+ox,q2.y+oy,za],
                [q2.x+ox,q2.y+oy,zb],[q1.x+ox,q1.y+oy,zb]],cc,'paper',0.98);
      }
    }
    if(uu>=U_FUSE){
      for(si=0;si<4;si++)
        band3(3.2, PZ0+si*PW+2, PZ0+(si+1)*PW-2, '#2E2438', '정착된 토너 화상');
    } else if(uu>=U_BTR2){
      ['K','C','M','Y'].forEach(function(n2,li){
        band3(3.2, PZ0+li*PW+4, PZ0+(li+1)*PW-4, TC(n2), '미정착 토너 ('+n2+')');
      });
    }
  }
  NM='';
  return A;
}

