/* ===== 렌더 ===== */
function vis(zn,tag){
  if(tag==='shell') return showShell && CAM[zn].shell!==false;
  if(tag==='paper') return PAPERZ.indexOf(zn)>=0;
  var m=MATCH[zn]; return m===null?true:m.indexOf(tag)>=0;
}
function fit(zn){
  var mn=[1e9,1e9,1e9],mx=[-1e9,-1e9,-1e9],all=ST.concat(dyn(zn)),i,j,k;
  for(i=0;i<all.length;i++){
    var f=all[i];
    if(!vis(zn,f.z)||f.l>0||f.z==='paper'||f.k==='dot'||f.k==='sym') continue;
    if(f.z==='shell'&&zn!=='all') continue;
    for(j=0;j<f.p.length;j++) for(k=0;k<3;k++){
      if(f.p[j][k]<mn[k])mn[k]=f.p[j][k]; if(f.p[j][k]>mx[k])mx[k]=f.p[j][k]; }
  }
  var ct=[(mn[0]+mx[0])/2,(mn[1]+mx[1])/2,(mn[2]+mx[2])/2];
  var c=CAM[zn],cy=Math.cos(c.yw),sy=Math.sin(c.yw),cp=Math.cos(c.pt),sp=Math.sin(c.pt);
  var hw=0,hh=0;
  for(i=0;i<all.length;i++){
    var f2=all[i];
    if(!vis(zn,f2.z)||f2.l>0||f2.z==='paper'||f2.k==='dot'||f2.k==='sym') continue;
    if(f2.z==='shell'&&zn!=='all') continue;
    for(j=0;j<f2.p.length;j++){
      var q=f2.p[j],x=q[0]-ct[0],y=q[1]-ct[1],z=q[2]-ct[2];
      var x1=x*cy+z*sy,z1=-x*sy+z*cy,y1=y*cp-z1*sp;
      if(Math.abs(x1)>hw)hw=Math.abs(x1); if(Math.abs(y1)>hh)hh=Math.abs(y1);
    }
  }
  fitS=Math.min(Math.min(214/(hw||1),268/(hh||1)),2.2);
  return {x:ct[0],y:ct[1],z:ct[2],s:fitS*zoom};
}
function render(){
  var all=ST.concat(dyn(zone)),list=[],i,j,lv=lod();
  for(i=0;i<all.length;i++){
    var f=all[i];
    if(!vis(zone,f.z)) continue;
    if(f.l>lv) continue;
    if(f.k==='s'&&f.o>=0.9&&f.n&&rotN(f.n)<=0) continue;
    var pr=[],ds=0;
    for(j=0;j<f.p.length;j++){ var q=proj(f.p[j]); pr.push(q); ds+=q[2]; }
    list.push({pr:pr,d:ds/f.p.length,f:f});
  }
  list.sort(function(a,b){return a.d-b.d;});
  var dmin=1e9,dmax=-1e9;
  for(i=0;i<list.length;i++){ if(list[i].d<dmin)dmin=list[i].d; if(list[i].d>dmax)dmax=list[i].d; }
  var sp=(dmax-dmin)||1,out=[];
  for(i=0;i<list.length;i++){
    var it=list[i],f2=it.f,near=(it.d-dmin)/sp;
    if(f2.k==='dot'){
      var q0=it.pr[0], rr=Math.max(1.2,(f2.r||3)*cam.s);
      out.push('<circle cx="'+q0[0].toFixed(1)+'" cy="'+q0[1].toFixed(1)+'" r="'+rr.toFixed(1)
        +'" fill="'+col(f2.c,1.18,near)+'" stroke="'+col(f2.c,1.8,near)
        +'" stroke-width="'+Math.max(0.5,rr*0.20).toFixed(2)+'"/>');
      continue;
    }
    if(f2.k==='sym'){
      var q1=it.pr[0], fs=Math.max(6,(f2.r||10)*cam.s);
      out.push('<text x="'+q1[0].toFixed(1)+'" y="'+(q1[1]+fs*0.36).toFixed(1)
        +'" text-anchor="middle" font-size="'+fs.toFixed(1)+'" font-weight="700" fill="'
        +col(f2.c,1.1,near)+'">'+f2.t+'</text>');
      continue;
    }
    var d='M'+it.pr.map(function(q){return q[0].toFixed(1)+' '+q[1].toFixed(1);}).join('L');
    if(f2.k==='e'){
      out.push('<path d="'+d+'" fill="none" stroke="'+f2.c+'" stroke-opacity="0.7" stroke-width="1.3"/>');
      continue;
    }
    var sh=1;
    if(f2.n){ var dd=Math.abs(f2.n[0]*LT[0]+f2.n[1]*LT[1]+f2.n[2]*LT[2]); sh=0.42+0.72*dd; }
    var so=(f2.z==='shell'&&zone!=='all')?0.3:1;
    out.push('<path d="'+d+'Z" fill="'+col(f2.c,sh,near)+'" fill-opacity="'+(f2.o*so).toFixed(3)
      +'" stroke="'+col(f2.c,sh*0.42,near)+'" stroke-width="0.7" stroke-linejoin="round"/>');
  }
  lastList=list;
  SCENE.innerHTML=out.join('')+labels()+hi();
}
function labels(){
  var show=pinned.map(function(p){ var q=proj(p.pos);
    return {t:p.t,px:q[0],py:q[1],left:(q[0]<ORX),ly:q[1]}; });
  ['L','R'].forEach(function(sd){
    var arr=show.filter(function(s){return sd==='L'?s.left:!s.left;});
    arr.sort(function(a,b){return a.ly-b.ly;});
    var i;
    for(i=0;i<arr.length;i++){
      if(i>0&&arr[i].ly-arr[i-1].ly<16) arr[i].ly=arr[i-1].ly+16;
      arr[i].ly=Math.max(22,Math.min(602,arr[i].ly));
    }
    for(i=arr.length-1;i>0;i--){ if(arr[i].ly-arr[i-1].ly<16) arr[i-1].ly=arr[i].ly-16; }
  });
  return show.map(function(s){
    var gx=s.left?GL:GR,el=s.left?gx+14:gx-14;
    return '<circle cx="'+s.px.toFixed(1)+'" cy="'+s.py.toFixed(1)
      +'" r="2.8" fill="#4FD1E8" stroke="#0A141C" stroke-width="1"/>'
      +'<path d="M'+s.px.toFixed(1)+' '+s.py.toFixed(1)+'L'+el.toFixed(1)+' '+s.ly.toFixed(1)
      +'L'+gx.toFixed(1)+' '+s.ly.toFixed(1)+'" fill="none" stroke="#4FD1E8"'
      +' stroke-opacity="0.55" stroke-width="0.9"/>'
      +'<text x="'+(gx+(s.left?-6:6)).toFixed(1)+'" y="'+(s.ly+3.6).toFixed(1)
      +'" text-anchor="'+(s.left?'end':'start')
      +'" font-family="\'IBM Plex Mono\',\'IBM Plex Sans KR\',\'Malgun Gothic\',monospace"'
      +' font-size="11.5" fill="#DCEAF2">'+s.t+'</text>';
  }).join('');
}
function hi(){
  if(!hoverPr) return '';
  return '<path d="M'+hoverPr.map(function(q){return q[0].toFixed(1)+' '+q[1].toFixed(1);}).join('L')
    +'Z" fill="none" stroke="#FFFFFF" stroke-opacity="0.85" stroke-width="1.8"/>';
}

/* ===== 히트 테스트 ===== */
function sp2(ev){
  var m=SVG.getScreenCTM(); if(!m) return null;
  var p=SVG.createSVGPoint(); p.x=ev.clientX; p.y=ev.clientY;
  return p.matrixTransform(m.inverse());
}
function inPoly(pts,x,y){
  var c=false,n=pts.length,i,j;
  for(i=0,j=n-1;i<n;j=i++){
    var xi=pts[i][0],yi=pts[i][1],xj=pts[j][0],yj=pts[j][1];
    if(((yi>y)!==(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi)) c=!c;
  }
  return c;
}
function pick(ev){
  var p=sp2(ev); if(!p) return null;
  for(var i=lastList.length-1;i>=0;i--){
    var it=lastList[i],f=it.f;
    if(!f.nm||f.k==='e'||f.o<0.25) continue;
    if(inPoly(it.pr,p.x,p.y)) return {f:f,pr:it.pr};
  }
  return null;
}
function ctr(f){
  var x=0,y=0,z=0,i;
  for(i=0;i<f.p.length;i++){x+=f.p[i][0];y+=f.p[i][1];z+=f.p[i][2];}
  return [x/f.p.length,y/f.p.length,z/f.p.length];
}
SVG.addEventListener('mousemove',function(ev){
  if(drag){ TIP.style.opacity='0'; return; }
  var h2=pick(ev);
  if(h2){
    SVG.style.cursor='pointer';
    if(h2.f.nm!==hoverNm||hoverPr!==h2.pr){ hoverNm=h2.f.nm; hoverPr=h2.pr; render(); }
    var r=STAGE.getBoundingClientRect();
    TIP.style.left=(ev.clientX-r.left)+'px';
    TIP.style.top=(ev.clientY-r.top)+'px';
    var de=desc(h2.f.nm);
    TIP.innerHTML=h2.f.nm+(de?'<span class="d">'+de+'</span>':'');
    TIP.style.opacity='1';
  } else {
    SVG.style.cursor='grab';
    if(hoverNm){ hoverNm=''; hoverPr=null; render(); }
    TIP.style.opacity='0';
  }
});
SVG.addEventListener('mouseleave',function(){
  TIP.style.opacity='0';
  if(hoverNm){ hoverNm=''; hoverPr=null; render(); }
});

