function setZoom(m){
  zoom=Math.max(0.7,Math.min(6,m)); camT.s=fitS*zoom;
  if(zoom<=1.02){ panX=0; panY=0; }
  document.getElementById('x3zro').textContent='×'+zoom.toFixed(1)+(lod()>=1?' · 세부':'');
  render();
}
document.getElementById('x3zin').addEventListener('click',function(){ setZoom(zoom*1.4); });
document.getElementById('x3zout').addEventListener('click',function(){ setZoom(zoom/1.4); });
SVG.addEventListener('wheel',function(e){ e.preventDefault();
  setZoom(zoom*(e.deltaY<0?1.13:1/1.13)); },{passive:false});
document.getElementById('x3reset').addEventListener('click',function(){ setZone(zone); });

var drag=false,pan=false,lx=0,ly=0,mv=0,dx0=0,dy0=0,pz=0,z0=1;
function down(e){
  if(e.touches&&e.touches.length===2){
    var a=e.touches[0],b=e.touches[1];
    pz=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY); z0=zoom; pan=true; drag=false;
    lx=(a.clientX+b.clientX)/2; ly=(a.clientY+b.clientY)/2; return;
  }
  drag=true; pan=(e.shiftKey||e.button===2); SVG.classList.add('drag');
  var p=e.touches?e.touches[0]:e; lx=p.clientX; ly=p.clientY; dx0=p.clientX; dy0=p.clientY; mv=0;
}
function move(e){
  if(e.touches&&e.touches.length===2&&pan){
    var a=e.touches[0],b=e.touches[1];
    var ds=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);
    if(pz>0) setZoom(z0*ds/pz);
    var mx=(a.clientX+b.clientX)/2,my=(a.clientY+b.clientY)/2;
    panX+=(mx-lx); panY+=(my-ly); lx=mx; ly=my;
    if(e.cancelable) e.preventDefault(); render(); return;
  }
  if(!drag) return;
  var p=e.touches?e.touches[0]:e;
  /* 터치에서 세로 제스처가 우세하면 회전하지 않고 페이지 스크롤에 양보 */
  if(e.touches && !pan){
    var tdx=Math.abs(p.clientX-dx0), tdy=Math.abs(p.clientY-dy0);
    if(tdy>10 && tdy>tdx*1.3){ drag=false; return; }
  }
  if(pan){ panX+=(p.clientX-lx); panY+=(p.clientY-ly); }
  else {
    yaw+=(p.clientX-lx)*0.008;
    pitch=Math.max(-0.5,Math.min(1.1,pitch+(p.clientY-ly)*0.006));
    yawT=yaw; pitchT=pitch;
  }
  lx=p.clientX; ly=p.clientY;
  mv=Math.abs(p.clientX-dx0)+Math.abs(p.clientY-dy0);
  if(e.cancelable) e.preventDefault();
  render();
}
function up(e){
  if(drag&&mv<5&&!pan&&e){
    var ev=e.changedTouches?e.changedTouches[0]:e;
    if(ev&&ev.clientX!==undefined){
      var h2=pick(ev);
      if(!h2) pinned=[];
      else {
        var nm=h2.f.nm,k=-1,i;
        for(i=0;i<pinned.length;i++) if(pinned[i].t===nm) k=i;
        if(k>=0) pinned.splice(k,1);
        else { if(pinned.length>=8) pinned.shift(); pinned.push({t:nm,pos:ctr(h2.f)}); }
      }
      render();
    }
  }
  drag=false; pan=false; pz=0; SVG.classList.remove('drag');
}
SVG.addEventListener('mousedown',down);
SVG.addEventListener('contextmenu',function(e){ e.preventDefault(); });
window.addEventListener('mousemove',move);
window.addEventListener('mouseup',up);
SVG.addEventListener('touchstart',down,{passive:true});
SVG.addEventListener('touchmove',move,{passive:false});
SVG.addEventListener('touchend',up);

var last=0;
function loop(ts){
  if(ts-last>28){
    last=ts; var need=false;
    var ax=camT.x-cam.x,ay=camT.y-cam.y,az=camT.z-cam.z,as=camT.s-cam.s;
    if(Math.abs(ax)+Math.abs(ay)+Math.abs(az)>0.4||Math.abs(as)>0.002){
      cam.x+=ax*0.12; cam.y+=ay*0.12; cam.z+=az*0.12; cam.s+=as*0.12; need=true;
    }
    var ay2=yawT-yaw,ap=pitchT-pitch;
    if(Math.abs(ay2)>0.004||Math.abs(ap)>0.004){ yaw+=ay2*0.12; pitch+=ap*0.12; need=true; }
    if(anim){ tt+=0.8; pu+=(duplex?0.0008:0.0017); if(pu>1)pu=0; need=true; }
    if(need) render();
  }
  requestAnimationFrame(loop);
}
setZone('all');
cam={x:camT.x,y:camT.y,z:camT.z,s:camT.s};
if(reduce){ anim=false; document.getElementById('x3anim').classList.remove('on'); }
render();
requestAnimationFrame(loop);
window.__T3={setZone:setZone,render:render,zoom:setZoom,ST:ST,dyn:dyn,proj:proj,desc:desc,
  set:function(y,p){yaw=y;pitch=p;yawT=y;pitchT=p;},
  jump:function(){cam={x:camT.x,y:camT.y,z:camT.z,s:camT.s};},
  tick:function(n){tt=n;},pu:function(n){pu=n;},lod:lod,col:function(c){drumSel=c;camT=fit('drum');render();},
  hit:function(x,y){for(var i=lastList.length-1;i>=0;i--){var it=lastList[i],f=it.f;
    if(!f.nm||f.k==='e'||f.o<0.25)continue; if(inPoly(it.pr,x,y))return f.nm;} return null;},
  labN:function(){return (SCENE.innerHTML.match(/<text/g)||[]).length;}};
})();

