var doc=document.getElementById('fdDoc');
var plate=document.getElementById('fdPlate'), paper=document.getElementById('fdPaper');
/* 용지를 경로 곡선에 맞춰 휘어진 띠로 그린다 */
var SLEN=126, THK=4.6;
function sheetD(uHead,len,thk){
  var head=uHead*LEN, tail=Math.max(0,head-len), N=16, A=[], B=[], i;
  for(i=0;i<=N;i++){
    var d=tail+(head-tail)*i/N;
    var p1=P.getPointAtLength(d), p2=P.getPointAtLength(Math.min(LEN,d+1.4));
    var tx=p2.x-p1.x, ty=p2.y-p1.y, m=Math.sqrt(tx*tx+ty*ty)||1;
    var nx=-ty/m*thk, ny=tx/m*thk;
    A.push((p1.x+nx).toFixed(1)+' '+(p1.y+ny).toFixed(1));
    B.unshift((p1.x-nx).toFixed(1)+' '+(p1.y-ny).toFixed(1));
  }
  return 'M'+A.join('L')+'L'+B.join('L')+'Z';
}
var lines=document.getElementById('fdLines');
var loop=document.getElementById('fdLoop'), loopL=document.getElementById('fdLoopL');
var run=!reduce, spd=1, stage=0, u=0, tt=0;

function apply(s){
  stage=s; var d=DS[s];
  document.getElementById('fdK').textContent=d.k;
  document.getElementById('fdT').textContent=d.t;
  document.getElementById('fdD').textContent=d.d;
  document.getElementById('fdP').textContent=d.p;
  Array.prototype.forEach.call(document.querySelectorAll('#fdSteps button'),function(b){
    b.classList.toggle('on',+b.dataset.s===s);
  });
  if(d.u!=null){ u=d.u; run=false;
    var pb=document.getElementById('fdPlay');
    pb.textContent='재생'; pb.classList.remove('on'); }
  frame(true);
}
document.getElementById('fdSteps').addEventListener('click',function(ev){
  var b=ev.target.closest('button'); if(!b) return; apply(+b.dataset.s);
});
document.getElementById('fdPlay').addEventListener('click',function(){
  run=!run; this.textContent=run?'일시정지':'재생'; this.classList.toggle('on',run);
});
document.getElementById('fdSlow').addEventListener('click',function(){
  spd=(spd===1)?0.3:1;
  this.textContent=(spd===1)?'저속':'표준속도'; this.classList.toggle('on',spd!==1);
});

watchVis('fdSvg');
function frame(once){
  if(!once && !isVis('fdSvg')){ requestAnimationFrame(function(){ frame(false); }); return; }
  if(run && !once){ u+=0.0020*spd; tt+=1.4*spd; }
  if(u>1) u=0;
  var p=at(u);
  doc.setAttribute('d', sheetD(u,SLEN,THK));

  /* Bottom Plate · 다발 상승 */
  var lift=6*(0.5+0.5*Math.sin(tt*0.035));
  plate.setAttribute('y',264-lift);
  paper.setAttribute('y',232-lift);
  lines.setAttribute('transform','translate(0,'+(-lift).toFixed(1)+')');

  /* 롤 회전 마커 */
  marks.forEach(function(m){
    var a=tt*m.r[6];
    m.el.setAttribute('d','M'+m.r[0]+' '+m.r[1]
      +'L'+(m.r[0]+m.r[2]*0.8*Math.cos(a*Math.PI/180)).toFixed(1)
      +' '+(m.r[1]+m.r[2]*0.8*Math.sin(a*Math.PI/180)).toFixed(1));
  });

  /* Regi 루프 */
  var lp=(u>0.60&&u<0.70);
  loop.setAttribute('opacity',lp?'0.95':'0');
  loopL.setAttribute('opacity',lp?'1':'0');

  /* 센서 점등 */
  sensEls.forEach(function(s){
    var on=(Math.abs(p.x-s.x)+Math.abs(p.y-s.y))<40;
    if(s.n==='Tray Level Sensor') on=(lift>4);
    if(s.n==='Tray Size Sensor') on=true;
    s.box.setAttribute('fill',on?'#008FB3':'#5A6E82');
  });

  var pos;
  if(u<0.20) pos='적재 · Lift Up';
  else if(u<0.43) pos='Nudger Roll';
  else if(u<0.50) pos='Feed / Retard 닙 (한 장만)';
  else if(u<0.60) pos='T/A Roll 반송';
  else if(u<0.72) pos='Regi 루프 · Skew 보정';
  else pos='전사부로';
  document.getElementById('fdPos').textContent=pos;

  if(!once) requestAnimationFrame(function(){ frame(false); });
}
apply(0);
if(reduce){ run=false; document.getElementById('fdPlay').textContent='재생'; }
else run=true;
requestAnimationFrame(function(){ frame(false); });
})();

