    var nx=-ty/m*thk, ny=tx/m*thk;
    A.push((p1.x+nx).toFixed(1)+' '+(p1.y+ny).toFixed(1));
    B.unshift((p1.x-nx).toFixed(1)+' '+(p1.y-ny).toFixed(1));
  }
  return 'M'+A.join('L')+'L'+B.join('L')+'Z';
}
var invG=document.getElementById('dfInvG'), cisG=document.getElementById('dfCIS');
var run=!reduce, spd=1, stage=0, m110=false, u=0, pass=1;

function apply(s){
  stage=s; var d=DS[s];
  document.getElementById('dfK').textContent=d.k;
  document.getElementById('dfT').textContent=d.t;
  document.getElementById('dfD').textContent=d.d;
  Array.prototype.forEach.call(document.querySelectorAll('#dfSteps button'),function(b){
    b.classList.toggle('on', +b.dataset.s===s);
  });
  if(d.u!=null){ u=d.u; run=false;
    var pb=document.getElementById('dfPlay');
    pb.textContent='재생'; pb.classList.remove('on'); }
  frame(true);
}
document.getElementById('dfSteps').addEventListener('click',function(e){
  var b=e.target.closest('button'); if(!b) return; apply(+b.dataset.s);
});
document.getElementById('dfPlay').addEventListener('click',function(){
  run=!run; this.textContent=run?'일시정지':'재생'; this.classList.toggle('on',run);
});
document.getElementById('dfSlow').addEventListener('click',function(){
  spd=(spd===1)?0.32:1;
  this.textContent=(spd===1)?'저속':'표준속도'; this.classList.toggle('on',spd!==1);
});
document.getElementById('dfMode').addEventListener('click',function(){
  m110=!m110; pass=1; u=0;
  this.textContent=m110?'DADF-130 보기':'DADF-110 보기';
  this.classList.toggle('on',m110);
  invG.setAttribute('opacity',m110?'1':'0');
  cisG.setAttribute('opacity',m110?'0':'1');
  document.getElementById('dfMdl').textContent=m110?'DADF-110':'DADF-130';
  document.getElementById('dfCap').textContent=m110?'DADF-110 · 3 Pass (반전)':'DADF-130 · One Pass';
  frame(true);
});

watchVis('dfSvg');
function frame(once){
  if(!once && !isVis('dfSvg')){ requestAnimationFrame(function(){ frame(false); }); return; }
  if(run && !once){ u+=0.0021*spd; }
  if(u>1){ u=0; if(m110) pass=(pass>=3?1:pass+1); }
  var p=at(u);
  doc.setAttribute('d', sheetD(u,SLEN,THK));

  /* 읽기 상태 : 130 은 표면(Scan)+이면(CIS), 110 은 Pass 별로 한 면씩 */
  var readF,readB;
  if(m110){
    readF=(pass>=1 && u>U_SCAN1) || pass>=2;
    readB=(pass>=2 && u>U_SCAN1) || pass>=3;
  } else {
    readF=(u>U_SCAN1);
    readB=(u>U_CIS+0.02);
  }
  fF.setAttribute('d', ribbon(u,SLEN,-2.2));
  fB.setAttribute('d', ribbon(u,SLEN, 2.2));
  fF.setAttribute('opacity', readF?1:0);
  fB.setAttribute('opacity', readB?1:0);

  var pos,rd;
  if(u<0.20) pos='원고 트레이 · Set Gate';
  else if(u<0.28) pos='Nudger → Feed Roll';
  else if(u<0.34) pos='APS · Feed In 검출';
  else if(u<0.45) pos='T/A Roll 반송';
  else if(u<0.58) pos='Regi 루프 · Skew 보정';
  else if(u<U_SCAN1) pos='Scan Position (CVT · 표면)';
  else if(u<0.80) pos=m110?'Out Roll':'Out Roll · CIS 이면 읽기';
  else pos=(m110&&pass<3)?'Exit Roll → 반전 경로':'Exit Roll · 배출';
  if(!readF && !readB) rd='읽기 전';
  else if(readF && !readB) rd=m110?('표면 완료 · '+pass+' Pass'):'표면 완료';
  else rd=m110?('양면 완료 · '+pass+' Pass'):'양면 완료';
  document.getElementById('dfPos').textContent=pos;
  document.getElementById('dfRead').textContent=rd;

  sensEls.forEach(function(s){
    var on=(Math.abs(p.x-s.p.x)+Math.abs(p.y-s.p.y))<24;
    s.box.setAttribute('fill', on?'#008FB3':'#5A6E82');
  });
  if(!once) requestAnimationFrame(function(){ frame(false); });
}
apply(0);
if(reduce){ run=false; document.getElementById('dfPlay').textContent='재생'; }
else run=true;
requestAnimationFrame(function(){ frame(false); });
})();

/* ================= Fig 07-1 용지 반송 ================= */
var pPath = document.getElementById('pPath');
var pDup  = document.getElementById('pPathDup');      /* 양면 전체 경로 (이동용) */
var pDupV = document.getElementById('pDupView');      /* 양면 우회 구간 (표시용) */
var dupLbl2 = document.getElementById('dupLbl2');
var pDupLen = pDup.getTotalLength();
/* 양면 경로 단계 경계 (경로 길이로 산출) */
var D_BTR1=0.169, D_FUSE1=0.221, D_EXIT=0.332, D_REV=0.358,
    D_OUT=0.576, D_REJOIN=0.699, D_BTR2=0.803;
var sheet = document.getElementById('sheet');
var sToner = document.getElementById('sheetToner');
var pStage = document.getElementById('pStage');
var dupLbl = document.getElementById('dupLbl');
var pLen = pPath.getTotalLength();
var pRun = !reduce, pU = 0, dupOn = false;
/* 용지를 경로 곡선에 맞춰 휘어진 띠로 그린다 */
var PSLEN = 118, PTHK = 4.8;
function curPath(){ return dupOn ? pDup : pPath; }
function curLen(){ return dupOn ? pDupLen : pLen; }
function pSheet(uHead, len, thk, offOnly){
  var PP=curPath(), LL=curLen();
  var head=uHead*LL, tail=Math.max(0,head-len), N=16, A=[], B=[], i;
  for(i=0;i<=N;i++){
    var d=tail+(head-tail)*i/N;
    var q1=PP.getPointAtLength(d), q2=PP.getPointAtLength(Math.min(LL,d+1.4));
    var tx=q2.x-q1.x, ty=q2.y-q1.y, m=Math.sqrt(tx*tx+ty*ty)||1;
    if(offOnly!=null){
      A.push((q1.x-ty/m*offOnly).toFixed(1)+' '+(q1.y+tx/m*offOnly).toFixed(1));
    } else {
      var nx=-ty/m*thk, ny=tx/m*thk;
      A.push((q1.x+nx).toFixed(1)+' '+(q1.y+ny).toFixed(1));
      B.unshift((q1.x-nx).toFixed(1)+' '+(q1.y-ny).toFixed(1));
    }
  }
  return offOnly!=null ? 'M'+A.join('L') : 'M'+A.join('L')+'L'+B.join('L')+'Z';
}

watchVis('paperSvg');
function pFrame(){
  if (!isVis('paperSvg')){ requestAnimationFrame(pFrame); return; }
  if (pRun) pU += (dupOn ? 0.0007 : 0.0016);
  if (pU > 1) pU = 0;
  var p = curPath().getPointAtLength(pU*curLen());
  sheet.setAttribute('d', pSheet(pU, PSLEN, PTHK));

  /* 진행률 기준 구간 판정 (경로상 y좌표로 판단) */
  var lbl, tw = 0, tcol = '#008FB3';
  if (dupOn){
    if (pU < D_BTR1)        { lbl = '① 급지 → T/A → Regi (Skew 보정)'; }
    else if (pU < D_FUSE1)  { lbl = '② 2차 전사 — 앞면에 토너 (1면)'; tw = 18; }
    else if (pU < D_EXIT)   { lbl = '③ 정착 — 앞면 완료'; tw = 18; tcol='#16181C'; }
    else if (pU < D_REV)    { lbl = '④ Exit 으로 일부 배출 → 여기서 멈춘다'; tw = 18; tcol='#16181C'; }
    else if (pU < D_OUT)    { lbl = '⑤ 반전 — 되돌려 바깥쪽 Duplex Path 로'; tw = 18; tcol='#16181C'; }
    else if (pU < D_REJOIN) { lbl = '⑥ 바깥쪽 우회 하강 — 기기 외측을 타고 내려간다'; tw = 18; tcol='#16181C'; }
    else if (pU < D_BTR2)   { lbl = '⑦ Regi 재진입 → 2차 전사 (뒷면 인쇄)'; tw = 18; tcol='#C8005F'; }
    else                    { lbl = '⑧ 정착 → Exit 배출 (양면 완료)'; tw = 18; tcol='#2E2438'; }
  } else {
    if (p.y > 292)      { lbl = '① 급지 — Nudger / Feed / Retard Roll (중복 급지 방지)'; }
    else if (p.y > 236) { lbl = '② Take Away — T/A Roll로 반송'; }
    else if (p.y > 168) { lbl = '③ Regi — Regi Roll에 부딪혀 루프 형성 · Skew 보정'; }
    else if (p.y > 100) { lbl = '④ 2차 전사 — 2nd BTR이 벨트의 토너를 용지로'; tw = 18; }
    else if (p.y > 60)  { lbl = '⑤ 정착 — Heat Roll + NIP Belt (NIP 12.6mm)'; tw = 18; tcol='#16181C'; }
    else                { lbl = '⑥ 배출 — Exit Sensor 검출 후 Exit 1로'; tw = 18; tcol='#16181C'; }
  }
  pStage.textContent = lbl;
  sToner.setAttribute('d', pSheet(pU, PSLEN, 0, -2.4));
  sToner.setAttribute('opacity', tw>0 ? 0.95 : 0);
  sToner.setAttribute('stroke', tcol);
  requestAnimationFrame(pFrame);
}
if (reduce){ pRun=false; document.getElementById('paperPlay').textContent='재생'; }
requestAnimationFrame(pFrame);
document.getElementById('paperPlay').addEventListener('click', function(){
  pRun = !pRun; this.textContent = pRun ? '일시정지' : '재생'; this.classList.toggle('on', pRun);
});
document.getElementById('paperDup').addEventListener('click', function(){
  dupOn = !dupOn; pU = 0;
  pDupV.setAttribute('opacity', dupOn ? '0.9' : '0');
  dupLbl.setAttribute('opacity', dupOn ? '1' : '0');
  dupLbl2.setAttribute('opacity', dupOn ? '1' : '0');
  pPath.setAttribute('opacity', dupOn ? '0.25' : '0.6');
  this.classList.toggle('on', dupOn);
});
})();
